        if isinstance(d, dict):
            for n in names:
                if n in d:
                    return d[n]
        for n in names:
            try:
                return obj[n]
            except Exception:
                pass
        return default

    def as_list(x):
        if x is None:
            return None
        if isinstance(x, list):
            return x
        if isinstance(x, tuple):
            return list(x)
        return x

    nodes = get_field(instance, ["nodes", "customers", "points", "locations"], None)
    demands = get_field(instance, ["demands", "demand"], None)
    capacity = get_field(instance, ["capacity", "vehicle_capacity", "cap"], None)
    distmat = get_field(instance, ["distance_matrix", "dist_matrix", "distances", "matrix"], None)
    coords = get_field(instance, ["coordinates", "coords", "xy", "positions"], None)
    depot = get_field(instance, ["depot", "depot_id"], 0)

    if capacity is None:
        cap_list = get_field(instance, ["vehicle_capacities"], None)
        if isinstance(cap_list, (list, tuple)) and cap_list:
            capacity = cap_list[0]
    if capacity is None:
        capacity = 0

    if nodes is None:
        n = get_field(instance, ["n", "num_nodes", "size"], None)
        if n is None:
            if isinstance(demands, (list, tuple)):
                n = len(demands)
            elif isinstance(distmat, (list, tuple)):
                n = len(distmat)
            else:
                n = 1
        nodes = list(range(n))
    else:
        nodes = list(nodes)

    if depot not in nodes:
        nodes = [depot] + [x for x in nodes if x != depot]

    customer_ids = [x for x in nodes if x != depot]

    def demand_of(i):
        if demands is None:
            return 0
        if isinstance(demands, dict):
            return demands.get(i, 0)
        if isinstance(demands, (list, tuple)):
            if 0 <= i < len(demands):
                return demands[i]
            return 0
        return 0

    def coord_of(i):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(i, None)
        if isinstance(coords, (list, tuple)) and 0 <= i < len(coords):
            return coords[i]
        return None

    def dist(i, j):
        if distmat is not None:
            if isinstance(distmat, dict):
                row = distmat.get(i, None)
                if isinstance(row, dict):
                    return row.get(j, 0)
                if isinstance(row, (list, tuple)) and 0 <= j < len(row):
                    return row[j]
                return 0
            if isinstance(distmat, (list, tuple)) and 0 <= i < len(distmat):
                row = distmat[i]
                if isinstance(row, (list, tuple)) and 0 <= j < len(row):
                    return row[j]
            return 0
        a = coord_of(i)
        b = coord_of(j)
        if a is None or b is None:
            return 0
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return (dx * dx + dy * dy) ** 0.5

    customer_ids.sort(key=lambda c: (dist(depot, c), -demand_of(c), c))

    unassigned = customer_ids[:]
    routes = []

    while unassigned:
        best_start = None
        best_key = None
        for c in unassigned:
            if demand_of(c) <= capacity:
                key = (dist(depot, c), -demand_of(c), c)
                if best_key is None or key < best_key:
                    best_key = key
                    best_start = c
        if best_start is None:
            best_start = unassigned[0]
        route = [best_start]
        load = demand_of(best_start)
        unassigned.remove(best_start)

        while True:
            last = route[-1]
            best_c = None
            best_score = None
            for c in unassigned:
                d = demand_of(c)
                if load + d > capacity:
                    continue
                score = dist(last, c) + dist(c, depot) - dist(last, depot)
                key = (score, dist(depot, c), -d, c)
                if best_score is None or key < best_score:
                    best_score = key
                    best_c = c
            if best_c is None:
                break
            route.append(best_c)
            load += demand_of(best_c)
            unassigned.remove(best_c)

        routes.append(route)

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def insertion_delta(route, idx, c):
        prevn = depot if idx == 0 else route[idx - 1]
        nextn = depot if idx == len(route) else route[idx]
        return dist(prevn, c) + dist(c, nextn) - dist(prevn, nextn)

    improved = True
    while improved:
        improved = False
        for i in range(len(routes)):
            if i >= len(routes):
                break
            for pos in range(len(routes[i])):
                if i >= len(routes):
                    break
                c = routes[i][pos]
                dc = demand_of(c)
                best_move = None
                best_gain = 0
                prevn = depot if pos == 0 else routes[i][pos - 1]
                nextn = depot if pos == len(routes[i]) - 1 else routes[i][pos + 1]
                rem_gain = dist(prevn, nextn) - dist(prevn, c) - dist(c, nextn)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if route_load(routes[j]) + dc > capacity:
                        continue
                    for ins in range(len(routes[j]) + 1):
                        add_delta = insertion_delta(routes[j], ins, c)
                        gain = rem_gain - add_delta
                        if gain > best_gain or (gain == best_gain and best_move is not None and (j, ins) < best_move):
                            best_gain = gain
                            best_move = (j, ins)
                if best_move is not None and best_gain > 0:
                    j, ins = best_move
                    routes[i].pop(pos)
                    routes[j].insert(ins, c)
                    if not routes[i]:
                        routes.pop(i)
                    improved = True
                    break
            if improved:
                break

    for r in range(len(routes)):
        route = routes[r]
        if len(route) < 4:
            continue
        changed = True
        while changed:
            changed = False
            m = len(route)
            for a in range(m - 2):
                for b in range(a + 2, m):
                    x1 = depot if a < 0 else route[a]
                    x2 = route[a + 1]
                    y1 = route[b]
                    y2 = depot if b == m - 1 else route[b + 1]
                    old = dist(x1, x2) + dist(y1, y2)
                    new = dist(x1, y1) + dist(x2, y2)
                    if new + 1e-12 < old:
                        route[a + 1:b + 1] = reversed(route[a + 1:b + 1])
                        changed = True
                        break
                if changed:
                    break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customer_ids if seen.get(c, 0) == 0]
    dupes = [c for c in seen if seen[c] > 1]

    for c in dupes:
        extra = seen[c] - 1
        for r in routes:
            while extra > 0 and c in r:
                r.remove(c)
                extra -= 1
            if extra == 0:
                break

    for c in missing:
        placed = False
        for r in routes:
            if route_load(r) + demand_of(c) <= capacity:
                best_idx = 0
                best_delta = None
                for idx in range(len(r) + 1):
                    dlt = insertion_delta(r, idx, c)
                    if best_delta is None or (dlt, idx) < (best_delta, best_idx):
                        best_delta = dlt
                        best_idx = idx
                r.insert(best_idx, c)
                placed = True
                break
        if not placed:
            routes.append([c])

    routes = [r for r in routes if r]
    return routes
